import{_ as t,o,c as n,ak as s}from"./chunks/framework.D598W_kV.js";const p=JSON.parse('{"title":"Conventions de nomenclature en C# dans Unity","description":"","frontmatter":{},"headers":[],"relativePath":"Ressource_Conventions_Nomenclature_CSharp.md","filePath":"Ressource_Conventions_Nomenclature_CSharp.md","lastUpdated":1770745010000}'),a={name:"Ressource_Conventions_Nomenclature_CSharp.md"};function r(d,e,c,i,l,u){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="conventions-de-nomenclature-en-c-dans-unity" tabindex="-1">Conventions de nomenclature en C# dans Unity <a class="header-anchor" href="#conventions-de-nomenclature-en-c-dans-unity" aria-label="Permalink to “Conventions de nomenclature en C# dans Unity”">​</a></h1><p>Dans le scripting C# ou la manipulation de GameObjects dans la scène, on utilise des conventions de nomenclature selon la catégorie d’identifiant et d&#39;objet. Quelques règles générales sont importantes:</p><ol><li>Ne jamais utiliser des <strong>espaces</strong> (❌ <code>Vaisseau 01</code>).</li><li>Ne jamais utiliser des <strong>accents</strong> (❌ <code>DéplacerJoueur()</code>).</li><li>Ne jamais utiliser des <strong>symboles</strong>, avec l&#39;exception du <code>_</code> (❌ <code>Score!</code>, ❌ <code>#Points</code>).</li></ol><h2 id="conventions-par-categorie" tabindex="-1">Conventions par catégorie <a class="header-anchor" href="#conventions-par-categorie" aria-label="Permalink to “Conventions par catégorie”">​</a></h2><div style="width:960px;"><table tabindex="0"><thead><tr><th>Catégorie</th><th>Convention</th><th>Exemple</th><th>Règle / Justification</th></tr></thead><tbody><tr><td><strong>Classe</strong></td><td><strong>PascalCase (première lettre majuscule)</strong></td><td><code>ControleurJoueur</code>, <code>SpawnerEnemis</code>, <code>GestionSante</code></td><td>Hérite de <code>MonoBehaviour</code> (plus commun). Nom reflète le rôle du script.</td></tr><tr><td><strong>Méthode</strong></td><td><strong>PascalCase</strong></td><td><code>DeplacerJoueur()</code>, <code>Start()</code></td><td>Méthodes d&#39;événement (ex: <code>Start()</code>, <code>Update()</code>) sont standard et ne doivent pas être modifiés. Les autres doivent être claires et descriptives avec un verbe à l&#39;infinitif.</td></tr><tr><td><strong>Variable (champ)</strong></td><td><strong>camelCase (première lettre minuscule)</strong></td><td><code>vitesseJoueur</code>, <code>sante</code>, <code>pointage</code></td><td>Utilisé pour les champs associés à la classe, soient <code>private</code> ou <code>public</code>.</td></tr><tr><td><strong>Variable locale</strong></td><td><strong>camelCase</strong></td><td><code>positionTemporaire</code>, <code>deltaTime</code></td><td>Variables utilisées dans les méthodes.</td></tr><tr><td><strong>Constante</strong></td><td><strong>UPPER_CASE</strong></td><td><code>SANTE_MAX</code>, <code>GRAVITE</code>, <code>VITESSE_JEU</code></td><td>Valeurs fixes, souvent utilisées comme paramètres ou facteurs de calcul, pour faciliter la compréhension et modification.</td></tr><tr><td><strong>Paramètre de méthode</strong></td><td><strong>camelCase</strong></td><td><code>message</code>, <code>valeurDegat</code>, <code>estSaut</code></td><td>Paramètres d&#39;entrée dans les méthodes.</td></tr><tr><td><strong>Nom d&#39;objet (dans le panneau Hierarchy)</strong></td><td><strong>PascalCase</strong></td><td><code>Joueur1</code>, <code>Joueur2</code>,<code>Ennemi</code>, <code>MenuInventaire</code></td><td>Utilisé dans les noms d&#39;objets ou de scripts dans la scène.</td></tr></tbody></table></div><h2 id="ressources-complementaires" tabindex="-1">Ressources complémentaires <a class="header-anchor" href="#ressources-complementaires" aria-label="Permalink to “Ressources complémentaires”">​</a></h2><ul><li><a href="https://unity.com/resources/c-sharp-style-guide-unity-6" target="_blank" rel="noreferrer">E-book (gratuit, EN) : Use a C# style guide for clean and scalable game code (Unity 6 edition)</a></li><li><a href="https://learn.microsoft.com/en-us/dotnet/csharp/fundamentals/coding-style/identifier-names" target="_blank" rel="noreferrer">C# Identifier Naming Conventions – Microsoft [EN]</a></li></ul>',7)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
